 COR("REVISAR PREGUNTAS",[("¿Qué pasó?","¿Qué le contó el viajero al capitán?","pregunta vaga: hay que precisar de quién se habla"),("¿Te gustó?","¿Te gustó la carta del capitán? ¿Por qué?","falta pedir las razones")],["Revisemos dos preguntas.","La primera es *vaga*: hay que precisar de quién se habla.","La segunda *no pide razones*: hay que sumarlas."]),
